// Turn the numbers into a short Telegram message (plain text, no names, no question text).
const s = $input.first().json;
const n = v => Number(v ?? 0).toLocaleString('en-US');
const people = v => `${n(v)} ${Number(v) === 1 ? 'person' : 'people'}`;
const day = new Date().toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
const lines = [
  `RAG health · ${day}`,
  '',
  `Library: ${n(s.files_searchable)} documents searchable · ${n(s.passages)} passages · ${n(s.images)} images · ${n(s.sheets)} spreadsheets`,
  `Last 24 h ingestion: ${n(s.ingested_24h)} processed · ${n(s.skipped_24h)} skipped · now failing: ${n(s.failing_now)} · retrying: ${n(s.retrying_now)}`,
  `Questions: ${n(s.questions_24h)} in 24 h (${people(s.people_24h)}) · ${n(s.questions_7d)} in 7 days (${people(s.people_7d)})`,
];
if (Number(s.erasures_24h) > 0) lines.push(`Privacy: ${n(s.erasures_24h)} erasure request(s) carried out`);
if (Number(s.failing_now) > 0) lines.push('', 'Needs a look — still failing:', s.failures);
if (Number(s.retrying_now) > 0) lines.push('', 'Some files are retrying (temporary errors); they will be picked up on later runs.');
lines.push('', 'Spend: Azure emails you at 50% / 80% of your monthly budget.');
// Telegram parses formatting; send HTML with &, < and > escaped so file names (underscores etc.) can't break it
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const out = lines.map(esc);
out[0] = `<b>${out[0]}</b>`;
return [{ json: { text: out.join('\n') } }];
